// Typed contract for the generated `phone-number.js` module.
//
// The `.js` file itself is @generated by `@mission-platform/vite-plugin-assemblyscript`
// (wasm inlined as base64); this declaration mirrors the exported surface of the
// AssemblyScript module in `assembly/index.ts`. Keep it in sync when the
// exported functions change.
export interface RawPhoneNumberExports {
  getCountryCodeForRegion(region: string): number;
  getRegionCodeForCountryCode(code: number): string;
  getRegionCodeForNumber(input: string, defaultRegion: string): string;
  getNationalSignificantNumber(input: string, defaultRegion: string): string;
  isPossibleNumber(input: string, defaultRegion: string): boolean;
  isValidNumber(input: string, defaultRegion: string): boolean;
  isValidNumberForRegion(input: string, region: string): boolean;
  getSupportedRegions(): string;
  getExampleNumber(region: string): string;
  getNumberType(input: string, defaultRegion: string): number;
  format(input: string, defaultRegion: string, fmt: number): string;
  formatAsYouType(input: string, region: string): string;
  reTest(
    program: Int32Array,
    classes: Int32Array,
    groupCount: number,
    input: string,
    requireEnd: boolean,
  ): number;
  reCaptures(
    program: Int32Array,
    classes: Int32Array,
    groupCount: number,
    input: string,
    start: number,
    requireEnd: boolean,
  ): Int32Array;
}

export function loadModule(): Promise<RawPhoneNumberExports>;

export function loadModuleSync(): RawPhoneNumberExports;
